SELECT CASE WHEN NOT COALESCE((SELECT count(*) FROM json_each(NEW.snapshot_json))=19 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.snapshot_json) WHERE key NOT IN('schemaVersion','id','organizationId','workspaceId','originJobId','uid','createdAt','revision','category','priority','language','originalDecision','reviewReasons','needsReview','humanCorrection','correctedBy','assigneeMembershipId','status','updatedAt')) AND NOT EXISTS(SELECT 1 FROM json_tree(NEW.snapshot_json) WHERE key IS NOT NULL GROUP BY parent,key HAVING count(*)>1) AND json_extract(NEW.snapshot_json,'$.schemaVersion')=1 AND json_type(NEW.snapshot_json,'$.schemaVersion')='integer' AND json_extract(NEW.snapshot_json,'$.id')=NEW.ticket_id AND json_extract(NEW.snapshot_json,'$.organizationId')=NEW.organization_id AND json_extract(NEW.snapshot_json,'$.workspaceId')=NEW.workspace_id AND json_type(NEW.snapshot_json,'$.revision')='integer' AND json_extract(NEW.snapshot_json,'$.revision')=NEW.revision AND json_extract(NEW.snapshot_json,'$.category')IN('bug','billing','supplier_invoice','appointment','order','after_sales','complaint','administration','human_resources','spam','solicitation','quote','credit_note','payment_reminder','receipt','product','refund','shipping','account','other') AND json_extract(NEW.snapshot_json,'$.priority')IN('low','normal','high','urgent') AND json_extract(NEW.snapshot_json,'$.language')IN('fr','de','it','en','other') AND json_extract(NEW.snapshot_json,'$.status')IN('open','in_progress','resolved') AND json_type(NEW.snapshot_json,'$.humanCorrection')IN('true','false') AND json_type(NEW.snapshot_json,'$.needsReview')IN('true','false') AND json_extract(NEW.snapshot_json,'$.reviewReasons')=json_extract(NEW.snapshot_json,'$.originalDecision.reviewReasons') AND json_extract(NEW.snapshot_json,'$.needsReview')=json_extract(NEW.snapshot_json,'$.originalDecision.needsReview'),0)THEN RAISE(ABORT,'us_ticket_invalid_record')END;
