AND((c.action='create' AND NEW.revision=1 AND json_extract(NEW.snapshot_json,'$.category')=json_extract(x.decision_json,'$.category') AND json_extract(NEW.snapshot_json,'$.priority')=json_extract(x.decision_json,'$.priority') AND json_extract(NEW.snapshot_json,'$.language')=json_extract(x.decision_json,'$.language') AND json_type(NEW.snapshot_json,'$.humanCorrection')='false' AND json_type(NEW.snapshot_json,'$.correctedBy')='null' AND json_extract(NEW.snapshot_json,'$.status')='open' AND json_extract(NEW.snapshot_json,'$.assigneeMembershipId')IS(SELECT json_extract(route.value,'$.membershipId') FROM international_us_support_ticket_routing settings,json_each(settings.snapshot_json,'$.routes')route JOIN international_workspace_members m ON m.organization_id=settings.organization_id AND m.membership_id=json_extract(route.value,'$.membershipId') AND m.revoked_at IS NULL AND m.role IN('owner','admin','member') WHERE settings.organization_id=NEW.organization_id AND settings.workspace_id=NEW.workspace_id AND settings.revision=c.routing_revision AND json_extract(settings.snapshot_json,'$.enabled')=1 AND json_extract(route.value,'$.category')=json_extract(x.decision_json,'$.category') AND json_extract(x.decision_json,'$.needsReview')=0 AND json_array_length(x.decision_json,'$.reviewReasons')=0 AND min(json_extract(x.decision_json,'$.categoryConfidence'),json_extract(x.decision_json,'$.priorityConfidence'),json_extract(x.decision_json,'$.languageConfidence'))>=max(json_extract(settings.snapshot_json,'$.threshold'),json_extract(j.grant_json,'$.threshold')) AND json_extract(x.decision_json,'$.model')='jev-1.13.0' AND json_extract(x.decision_json,'$.recipeVersion')='us-support-text:support-2026-09-28-solicitation-v6'))
OR(c.action='correct' AND json_extract(NEW.snapshot_json,'$.category')=json_extract(c.request_json,'$.category') AND json_extract(NEW.snapshot_json,'$.priority')=json_extract(c.request_json,'$.priority') AND json_extract(NEW.snapshot_json,'$.language')=json_extract(c.request_json,'$.language') AND json_type(NEW.snapshot_json,'$.humanCorrection')='true' AND json_extract(NEW.snapshot_json,'$.correctedBy')=c.actor_user_id AND json_remove(NEW.snapshot_json,'$.revision','$.updatedAt','$.category','$.priority','$.language','$.humanCorrection','$.correctedBy')=json_remove((SELECT snapshot_json FROM international_us_support_ticket_revisions WHERE organization_id=NEW.organization_id AND workspace_id=NEW.workspace_id AND ticket_id=NEW.ticket_id AND revision=NEW.revision-1),'$.revision','$.updatedAt','$.category','$.priority','$.language','$.humanCorrection','$.correctedBy'))
OR(c.action='assign' AND json_extract(NEW.snapshot_json,'$.assigneeMembershipId')IS json_extract(c.request_json,'$.assigneeMembershipId') AND json_remove(NEW.snapshot_json,'$.revision','$.updatedAt','$.assigneeMembershipId')=json_remove((SELECT snapshot_json FROM international_us_support_ticket_revisions WHERE organization_id=NEW.organization_id AND workspace_id=NEW.workspace_id AND ticket_id=NEW.ticket_id AND revision=NEW.revision-1),'$.revision','$.updatedAt','$.assigneeMembershipId'))
OR(c.action='set_status' AND json_extract(NEW.snapshot_json,'$.status')=json_extract(c.request_json,'$.status') AND json_remove(NEW.snapshot_json,'$.revision','$.updatedAt','$.status')=json_remove((SELECT snapshot_json FROM international_us_support_ticket_revisions WHERE organization_id=NEW.organization_id AND workspace_id=NEW.workspace_id AND ticket_id=NEW.ticket_id AND revision=NEW.revision-1),'$.revision','$.updatedAt','$.status'))))THEN RAISE(ABORT,'us_ticket_invalid_record')END;
SELECT CASE WHEN json_extract(NEW.snapshot_json,'$.assigneeMembershipId')IS NOT NULL AND EXISTS(SELECT 1 FROM international_us_support_ticket_commands c WHERE c.organization_id=NEW.organization_id AND c.workspace_id=NEW.workspace_id AND c.command_id=NEW.command_id AND c.action IN('create','assign'))AND NOT EXISTS(SELECT 1 FROM international_workspace_members m WHERE m.organization_id=NEW.organization_id AND m.membership_id=json_extract(NEW.snapshot_json,'$.assigneeMembershipId') AND m.revoked_at IS NULL AND m.role IN('owner','admin','member'))THEN RAISE(ABORT,'us_ticket_assignee_unavailable')END;
END;
