CREATE TRIGGER international_us_support_ticket_routing_insert BEFORE INSERT ON international_us_support_ticket_routing BEGIN
SELECT CASE WHEN EXISTS(SELECT 1 FROM international_us_support_ticket_routing WHERE command_id=NEW.command_id OR(organization_id=NEW.organization_id AND workspace_id=NEW.workspace_id AND revision=NEW.revision))THEN RAISE(ABORT,'us_ticket_immutable')END;
SELECT CASE WHEN NOT COALESCE((SELECT count(*) FROM json_each(NEW.snapshot_json))=5 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.snapshot_json) WHERE key NOT IN('schemaVersion','revision','enabled','threshold','routes')) AND NOT EXISTS(SELECT 1 FROM json_tree(NEW.snapshot_json) WHERE key IS NOT NULL GROUP BY parent,key HAVING count(*)>1) AND json_extract(NEW.snapshot_json,'$.schemaVersion')=1 AND json_type(NEW.snapshot_json,'$.schemaVersion')='integer' AND json_extract(NEW.snapshot_json,'$.revision')=NEW.revision AND json_type(NEW.snapshot_json,'$.revision')='integer' AND json_type(NEW.snapshot_json,'$.enabled')IN('true','false') AND json_type(NEW.snapshot_json,'$.threshold')IN('integer','real') AND json_extract(NEW.snapshot_json,'$.threshold') BETWEEN 0 AND 1 AND json_type(NEW.snapshot_json,'$.routes')='array' AND json_array_length(NEW.snapshot_json,'$.routes')<=20 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.snapshot_json,'$.routes')r WHERE json_type(r.value)<>'object' OR(SELECT count(*)FROM json_each(r.value))<>2 OR EXISTS(SELECT 1 FROM json_each(r.value)WHERE key NOT IN('category','membershipId'))OR json_extract(r.value,'$.category')NOT IN('bug','billing','supplier_invoice','appointment','order','after_sales','complaint','administration','human_resources','spam','solicitation','quote','credit_note','payment_reminder','receipt','product','refund','shipping','account','other') OR NOT EXISTS(SELECT 1 FROM international_workspace_members m WHERE m.organization_id=NEW.organization_id AND m.membership_id=json_extract(r.value,'$.membershipId') AND m.revoked_at IS NULL AND m.role IN('owner','admin','member')))AND NOT EXISTS(SELECT 1 FROM json_each(NEW.snapshot_json,'$.routes')GROUP BY json_extract(value,'$.category')HAVING count(*)>1) AND EXISTS(SELECT 1 FROM international_us_support_ticket_commands c WHERE c.organization_id=NEW.organization_id AND c.workspace_id=NEW.workspace_id AND c.command_id=NEW.command_id AND c.action='save_routing' AND c.entity_revision=NEW.revision AND json_extract(NEW.snapshot_json,'$.enabled')=json_extract(c.request_json,'$.enabled') AND json_extract(NEW.snapshot_json,'$.threshold')=json_extract(c.request_json,'$.threshold') AND json_extract(NEW.snapshot_json,'$.routes')=json_extract(c.request_json,'$.routes') AND NOT EXISTS(SELECT 1 FROM international_us_support_ticket_audit a WHERE a.command_id=c.command_id)),0)THEN RAISE(ABORT,'us_ticket_assignee_unavailable')END;END;
